order-radius: 8px 8px 30px 30px;     position: relative; overflow: hidden;     box-shadow: 0 20px 60px rgba(0,0,0,0.8), inset 2px 2px 6px rgba(255,255,255,0.05);     clip-path: polygon(10% 0%, 90% 0%, 100% 100%, 0% 100%);   }   .coffee-surface {     position: absolute; top: 14px; left: 12px; right: 12px; height: 50px;     background: radial-gradient(ellipse, #4a2800 0%, #2a1500 60%, #1a0a00 100%);     border-radius: 50%;     box-shadow: 0 4px 20px rgba(0,0,0,0.5);   }   .crema {     position: absolute; top: 16px; left: 18px; right: 18px; height: 20px;     background: radial-gradient(ellipse, #c8813a 0%, #9a5a1a 60%);     border-radius: 50%;     opacity: 0.85;   }   .liquid {     position: absolute; top: 50px; bottom: 0; left: 0; right: 0;     background: linear-gradient(180deg, #1a0800 0%, #0d0400 100%);   }   .highlight {     position: absolute; top: 0; left: 10px; width: 20px; bottom: 0;     background: linear-gradient(to right, rgba(255,255,255,0.06), transparent);   }   .saucer {     position: absolute; bottom: -12px; left: -20px; right: -20px; height: 24px;     background: linear-gradient(160deg, #3a3a3a, #1a1a1a);     border-radius: 50%;     box-shadow: 0 8px 20px rgba(0,0,0,0.6);   }   .label {     text-align: center;   }   .item-name {     font-size: 52px;     font-family: ''Georgia'', serif;     color: #e8c97a;     letter-spacing: 4px;     text-shadow: 0 2px 20px rgba(232,201,122,0.3);   }   .item-sub {     font-size: 16px;     color: rgba(255,255,255,0.35);     letter-spacing: 6px;     text-transform: uppercase;     margin-top: 8px;   }   .divider {     width: 60px; height: 1px;     background: linear-gradient(to right, transparent, #e8c97a, transparent);     margin: 12px auto;   } </style> </head> <body> <div class=\"bg\"></div> <div class=\"noise\"></div> <div class=\"card\">   <div class=\"cup-wrap\">     <div class=\"steam\">       <div class=\"steam-line\"></div>       <div class=\"steam-line\"></div>       <div class=\"steam-line\"></div>     </div> 