INSERT INTO "public"."recipes" ("id", "merchant_id", "name", "description", "instructions", "servings", "created_at", "updated_at") VALUES
	('d2e3f4a5-b6c7-4d8e-9f0a-1b2c3d4e5f6a', '2add44cb-f498-4653-aca3-a8f0ca258e70', 'Classic Latte Recipe', 'Standard 12oz latte preparation', '1. Pull 2 shots of espresso (18g in, 36g out, 25-30 seconds)\n2. Steam 10oz whole milk to 140-150°F with microfoam\n3. Pour milk over espresso, holding back foam\n4. Top with 1/4 inch of microfoam\n5. Optional: latte art', 1, '2025-12-03 19:14:12.557467+00', '2025-12-03 19:14:12.557467+00'),
	('e3f4a5b6-c7d8-4e9f-0a1b-2c3d4e5f6a7b', '2add44cb-f498-4653-aca3-a8f0ca258e70', 'Caramel Macchiato Recipe', 'Signature caramel macchiato', '1. Add 2 pumps vanilla syrup to cup\n2. Steam 10oz milk to 140-150°F\n3. Pour milk into cup over vanilla\n4. Pull 2 shots espresso and pour over milk (marking it)\n5. Drizzle caramel sauce in crosshatch pattern', 1, '2025-12-03 19:14:12.557467+00', '2025-12-03 19:14:12.557467+00'),
	('f4a5b6c7-d8e9-4f0a-1b2c-3d4e5f6a7b8c', '2add44cb-f498-4653-aca3-a8f0ca258e70', 'Cold Brew Concentrate', 'Batch cold brew concentrate (makes 64oz)', '1. Coarsely grind 12oz coffee beans\n2. Combine with 64oz cold filtered water in container\n3. Stir to saturate all grounds\n4. Cover and refrigerate for 18-24 hours\n5. Strain through fine mesh filter twice\n6. Store concentrate up to 2 weeks\n7. Serve: dilute 1:1 with water or milk', 16, '2025-12-03 19:14:12.557467+00', '2025-12-03 19:14:12.557467+00'),
	('a5b6c7d8-e9f0-4a1b-2c3d-4e5f6a7b8c9d', '2add44cb-f498-4653-aca3-a8f0ca258e70', 'Avocado Toast Recipe', 'Classic avocado toast with everything seasoning', '1. Toast sourdough slice until golden\n2. Halve and pit 1/2 ripe avocado\n3. Scoop avocado onto toast\n4. Smash with fork, leaving some texture\n5. Season with salt, pepper, lemon juice\n6. Top with everything bagel seasoning\n7. Drizzle with olive oil', 1, '2025-12-03 19:14:12.557467+00', '2025-12-03 19:14:12.557467+00');
